  3	import com.loja.domain.*;
  4	import com.loja.dto.OrderRequest;
  5	import com.loja.dto.PaymentRequest;
  6	import com.loja.exception.ErrorCode;
  7	import com.loja.repository.CustomerRepository;
  8	import com.loja.repository.NotificationRepository;
  9	import com.loja.repository.OrderRepository;
 10	import com.loja.repository.ProductRepository;
 11	import org.springframework.stereotype.Service;
 12	import org.springframework.transaction.annotation.Transactional;
 13	
 14	import java.time.Duration;
 15	import java.time.Instant;
 16	import java.util.HashMap;
 17	import java.util.List;
 18	import java.util.Map;
 19	
 20	@Service
 21	public class OrderService {
 22	
 23	    private final OrderRepository orderRepository;
 24	    private final ProductRepository productRepository;
 25	    private final CustomerRepository customerRepository;
 26	    private final NotificationRepository notificationRepository;
 27	    private final CheckoutService checkoutService;
 28	
 29	    private final Map<String, PaymentProcessingResult> processedPayments = new HashMap<>();
 30	
 31	    public OrderService(
 32	            OrderRepository orderRepository,
 33	            ProductRepository productRepository,
 34	            CustomerRepository customerRepository,
 35	            NotificationRepository notificationRepository,
 36	            CheckoutService checkoutService) {
 37	        this.orderRepository = orderRepository;
 38	        this.productRepository = productRepository;
 39	        this.customerRepository = customerRepository;
 40	        this.notificationRepository = notificationRepository;
 41	        this.checkoutService = checkoutService;
 42	    }
 43	
 44	    @Transactional
 45	    public Order createOrder(OrderRequest request) {
 46	        OrderSummary summary = checkoutService.calculateSummary(request);
 47	
 48	        List<OrderItem> items = request.items().stream()
 49	            .map(i -> new OrderItem(i.sku(), i.quantity()))
 50	            .toList();
 51	
 52	        Order order = new Order(request.customer().cpf(), items, summary);
 53	
 54	        customerRepository.findById(request.customer().cpf())
 55	            .orElseGet(() -> customerRepository.save(new Customer(request.customer().cpf())));
 56	
 57	        return orderRepository.save(order);
 58	    }
 59	
 60	    @Transactional
 61	    public Order processPayment(Long orderId, PaymentRequest request) {
 62	        if (request.transactionId() == null || request.paidAt() == null) {
 63	            throw ErrorCode.INVALID_ORDER.asException();
 64	        }
 65	
 66	        Order order = orderRepository.findById(orderId)
 67	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
 68	
 69	        String paymentKey = orderId + ":" + request.transactionId();
 70	
 71	        synchronized (processedPayments) {
 72	            if (processedPayments.containsKey(paymentKey)) {
 73	                PaymentProcessingResult cached = processedPayments.get(paymentKey);
 74	                if (cached.success()) {
 75	                    return orderRepository.findById(orderId).orElseThrow();
 76	                } else {
 77	                    throw cached.error().asException();
 78	                }
 79	            }
 80	        }
 81	
 82	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
 83	            if (order.getPaymentTransactionId() != null &&
 84	                order.getPaymentTransactionId().equals(request.transactionId())) {
 85	                synchronized (processedPayments) {
 86	                    processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
 87	                }
 88	                return order;
 89	            }
 90	            synchronized (processedPayments) {
 91	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.OPERATION_NOT_ALLOWED));
 92	            }
 93	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
 94	        }
 95	
 96	        Duration elapsed = Duration.between(order.getCreatedAt(), request.paidAt());
 97	        if (elapsed.toHours() > 48) {
 98	            order.cancel();
 99	            orderRepository.save(order);
100	            notificationRepository.save(new Notification(
101	                order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
102	            ));
103	            synchronized (processedPayments) {
104	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.ORDER_EXPIRED));
105	            }
106	            throw ErrorCode.ORDER_EXPIRED.asException();
107	        }
108	
109	        try {
110	            decreaseStock(order);
111	        } catch (IllegalStateException e) {
112	            order.cancel();
113	            orderRepository.save(order);
114	            notificationRepository.save(new Notification(
115	                order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
116	            ));
117	            synchronized (processedPayments) {
118	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.INSUFFICIENT_STOCK));
119	            }
120	            throw ErrorCode.INSUFFICIENT_STOCK.asException();
121	        }
122	
123	        order.markAsPaid(request.transactionId());
124	        orderRepository.save(order);
125	
126	        Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
127	            .orElseThrow(() -> ErrorCode.CUSTOMER_NOT_FOUND.asException());
128	        customer.addCredit(order.getSummary().nextPurchaseCredit());
129	        customerRepository.save(customer);
130	
131	        notificationRepository.save(new Notification(
132	            order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId
133	        ));
134	
135	        synchronized (processedPayments) {
136	            processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
137	        }
138	
139	        return order;
140	    }
141	
142	    @Transactional
143	    public Order shipOrder(Long orderId, String trackingCode) {
144	        if (trackingCode == null || trackingCode.isBlank()) {
145	            throw ErrorCode.INVALID_ORDER.asException();
146	        }
147	
148	        Order order = orderRepository.findById(orderId)
149	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
150	
151	        if (order.getStatus() != OrderStatus.PAID) {
152	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
153	        }
154	
155	        order.ship(trackingCode);
156	        orderRepository.save(order);
157	
158	        notificationRepository.save(new Notification(
159	            order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId
160	        ));
161	
162	        return order;
163	    }
164	
165	    @Transactional
166	    public Order deliverOrder(Long orderId) {
167	        Order order = orderRepository.findById(orderId)
168	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
169	
170	        if (order.getStatus() != OrderStatus.SHIPPED) {
171	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
172	        }
173	
174	        order.deliver();
175	        return orderRepository.save(order);
176	    }
177	
178	    @Transactional
179	    public Order cancelOrder(Long orderId) {
180	        Order order = orderRepository.findById(orderId)
181	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
182	
183	        if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
184	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
185	        }
186	
187	        boolean wasPaid = order.isPaid();
188	
189	        order.cancel();
190	        orderRepository.save(order);
191	
192	        if (wasPaid) {
193	            increaseStock(order);
194	
195	            Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
196	                .orElseThrow(() -> ErrorCode.CUSTOMER_NOT_FOUND.asException());
197	            customer.removeCredit(order.getSummary().nextPurchaseCredit());
198	            customerRepository.save(customer);
199	        }
200	
201	        notificationRepository.save(new Notification(
202	            order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
203	        ));
204	
205	        return order;
206	    }
207	
208	    @Transactional(readOnly = true)
209	    public Order getOrder(Long orderId) {
210	        return orderRepository.findById(orderId)
211	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
212	    }
213	
214	    private void decreaseStock(Order order) {
215	        for (OrderItem item : order.getItems()) {
216	            Product product = productRepository.findBySkuForUpdate(item.getSku())
217	                .orElseThrow(() -> ErrorCode.UNKNOWN_PRODUCT.asException());
218	            product.decreaseStock(item.getQuantity());
219	            productRepository.save(product);
220	        }
221	    }
222	
223	    private void increaseStock(Order order) {
224	        for (OrderItem item : order.getItems()) {
225	            Product product = productRepository.findBySkuForUpdate(item.getSku())
226	                .orElseThrow(() -> ErrorCode.UNKNOWN_PRODUCT.asException());
227	            product.increaseStock(item.getQuantity());
228	            productRepository.save(product);
229	        }
230	    }
231	
232	    private record PaymentProcessingResult(boolean success, ErrorCode error) {}
233	}

