 63	            throw ErrorCode.INVALID_ORDER.asException();
 64	        }
 65	
 66	        Order order = orderRepository.findById(orderId)
 67	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
 68	
 69	        String paymentKey = orderId + ":" + request.transactionId();
 70	
 71	        synchronized (processedPayments) {
 72	            if (processedPayments.containsKey(paymentKey)) {
 73	                PaymentProcessingResult cached = processedPayments.get(paymentKey);
 74	                if (cached.success()) {
 75	                    return orderRepository.findById(orderId).orElseThrow();
 76	                } else {
 77	                    throw cached.error().asException();
 78	                }
 79	            }
 80	        }
 81	
 82	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
 83	            if (order.getPaymentTransactionId() != null &&
 84	                order.getPaymentTransactionId().equals(request.transactionId())) {
 85	                synchronized (processedPayments) {
 86	                    processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
 87	                }
 88	                return order;
 89	            }
 90	            synchronized (processedPayments) {
 91	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.OPERATION_NOT_ALLOWED));
 92	            }
 93	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
 94	        }
 95	
 96	        Duration elapsed = Duration.between(order.getCreatedAt(), request.paidAt());
 97	        if (elapsed.toHours() > 48) {
 98	            order.cancel();
 99	            orderRepository.save(order);
100	            notificationRepository.save(new Notification(
101	                order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
102	            ));
103	            synchronized (processedPayments) {
104	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.ORDER_EXPIRED));
105	            }
106	            throw ErrorCode.ORDER_EXPIRED.asException();
107	        }
108	
109	        try {
110	            decreaseStock(order);
111	        } catch (IllegalStateException e) {
112	            order.cancel();
113	            orderRepository.save(order);
114	            notificationRepository.save(new Notification(
115	                order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
116	            ));
117	            synchronized (processedPayments) {
118	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.INSUFFICIENT_STOCK));
119	            }
120	            throw ErrorCode.INSUFFICIENT_STOCK.asException();
121	        }
122	
123	        order.markAsPaid(request.transactionId());
124	        orderRepository.save(order);
125	
126	        Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
127	            .orElseThrow(() -> ErrorCode.CUSTOMER_NOT_FOUND.asException());
128	        customer.addCredit(order.getSummary().nextPurchaseCredit());
129	        customerRepository.save(customer);
130	
131	        notificationRepository.save(new Notification(
132	            order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId
133	        ));
134	
135	        synchronized (processedPayments) {
136	            processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
137	        }
138	
139	        return order;
140	    }
